#!/bin/bash
# gen-ffmpeg.sh <builddir> <platform: x64|Win32>
#
# Maintainer-time only: turns a configured-and-built out-of-tree ffmpeg build
# directory (msvc/regen/regen.cmd makes one per platform) into what MSBuild needs:
#   msvc/ffmpeg/generated/<platform>/   configure's outputs: config.h, config_components.h,
#                                       config.asm, avconfig.h, ffversion.h, the *_list.c
#                                       component tables and the .def export lists
#   msvc/ffmpeg/items-<lib>-<platform>.props   one source list per DLL
#   msvc/ffmpeg/nasm-<platform>.props          assembler flags for the platform
#   msvc/ffmpeg/<lib>.vcxproj                  project shells (written only if absent)
# The object list for each DLL is taken from make's own response files, and the
# object-to-source mapping from a dry run of make, so the projects compile exactly
# what the configured Makefiles would.
set -e
B=$(cd "$1" && pwd); PLAT=$2; CC=${3:-cl}
[ "$PLAT" = x64 ] || [ "$PLAT" = Win32 ] || { echo "platform must be x64 or Win32"; exit 1; }
[ "$CC" = cl ] || [ "$CC" = clang ] || { echo "compiler must be cl or clang"; exit 1; }
P=$(cd "$(dirname "$0")/../ffmpeg" && pwd)       # project shells live here
O="$P/$CC"; mkdir -p "$O"                        # per-compiler generated output
SRC=$(sed -n 's|^SRC_PATH=||p' "$B/ffbuild/config.mak")
[ -d "$SRC" ] || { echo "cannot find SRC_PATH in $B/ffbuild/config.mak"; exit 1; }
LIBS="avutil swresample swscale avcodec avformat avfilter"

echo "== $PLAT: capturing make command list"
( cd "$B" && make -nB V=1 > cmds.txt 2>&1 ) || { echo "make -nB failed"; exit 1; }
C="$B/cmds.txt"
# cl writes objects with -Fo<obj>, clang with -o <obj>
grep -E '^(cl\.exe|clang) ' "$C" | grep ' -c ' | awk '{o="";s=""; for(i=1;i<=NF;i++){ if($i ~ /^-Fo/) o=substr($i,4); if($i=="-o") o=$(i+1); if($i ~ /\.c$/) s=$i } print o" "s}' > "$B/map-c.txt"
grep '^nasm'  "$C" | awk '{o="";s=""; for(i=1;i<=NF;i++){ if($i=="-o") o=$(i+1); if($i ~ /\.asm$/) s=$i } print o" "s}' > "$B/map-asm.txt"
grep 'mswindres' "$C" | awk '{o="";s=""; for(i=1;i<=NF;i++){ if($i=="-o") o=$(i+1); if($i ~ /\.rc$/) s=$i } print o" "s}' > "$B/map-rc.txt"
echo "   $(wc -l < "$B/map-c.txt") C, $(wc -l < "$B/map-asm.txt") asm, $(wc -l < "$B/map-rc.txt") rc"
X86ASMFLAGS=$(sed -n 's|^X86ASMFLAGS=||p' "$B/ffbuild/config.mak")

G="$O/generated/$PLAT"; rm -rf "$G"; for l in $LIBS; do mkdir -p "$G/lib$l"; done; mkdir -p "$G/libswscale/x86"
# FFMPEG_CONFIGURATION would otherwise embed the maintainer's absolute paths
sed -E "s/ ?-(I|LIBPATH:)[^ ']+//g" "$B/config.h" > "$G/config.h"
cp "$B"/config_components.h "$B"/config.asm "$B"/config_components.asm "$G/"
cp "$B"/libavutil/avconfig.h "$B"/libavutil/ffversion.h "$G/libavutil/"
cp "$B"/libavcodec/*_list.c "$G/libavcodec/"; cp "$B"/libavformat/*_list.c "$G/libavformat/"; cp "$B"/libavfilter/*_list.c "$G/libavfilter/"
[ -f "$B/libswscale/x86/uops_macros.gen.asm" ] && cp "$B/libswscale/x86/uops_macros.gen.asm" "$G/libswscale/x86/"

for lib in $LIBS; do
  def=$(ls "$B"/lib$lib/$lib-lav-*.def); dll=$(basename "$def" .def)
  cp "$def" "$G/lib$lib/"
  linkline=$(grep "mslink" "$C" | grep -v '^LDFLAGS' | grep -- "-out:lib$lib/$dll.dll")
  deps=$(echo "$linkline" | tr ' ' '\n' | grep '\.lib$' | grep -v -- '-implib' | sort -u | tr '\n' ';')
  # object list: make's response file when the toolchain uses one (cl), else the link line itself (clang)
  objs="$B/lib$lib/$dll.dll.objs"
  [ -f "$objs" ] || { objs="$B/lib$lib/$dll.objlist"; echo "$linkline" | tr ' ' '\n' | grep '\.o$' | tr '\n' ' ' > "$objs"; }
  IT="$O/items-$lib-$PLAT.props"
  {
    echo '<?xml version="1.0" encoding="utf-8"?>'
    echo "<!-- generated by msvc/regen/gen-ffmpeg.sh for $PLAT from ffmpeg $(cat "$B/.version" 2>/dev/null) - do not edit -->"
    echo '<Project xmlns="http://schemas.microsoft.com/developer/msbuild/2003">'
    echo "  <PropertyGroup>"
    echo "    <FFmpegDllName>$dll</FFmpegDllName>"
    echo "    <FFmpegLinkDeps>$deps</FFmpegLinkDeps>"
    echo "  </PropertyGroup>"
    echo "  <ItemGroup>"
    tr ' ' '\n' < "$objs" | grep -v '^$' | awk -v src="$SRC/" -v mapc="$B/map-c.txt" -v mapa="$B/map-asm.txt" -v mapr="$B/map-rc.txt" '
      function w(p) { gsub(/\//, "\\", p); return p }
      function rel(p) { if (index(p, src) == 1) return "$(FFmpegSrc)" w(substr(p, length(src)+1)); if (p ~ /^\//) return p; return "$(FFmpegGen)" w(p) }
      BEGIN { while ((getline l < mapc) > 0) { split(l, a, " "); C[a[1]] = a[2] }
              while ((getline l < mapa) > 0) { split(l, a, " "); A[a[1]] = a[2] }
              while ((getline l < mapr) > 0) { split(l, a, " "); R[a[1]] = a[2] } }
      { o = $1; objrel = o; sub(/\.o$/, "", objrel); objrel = w(objrel)
        if (o in C) { printf "    <ClCompile Include=\"%s\"><ObjectFileName>$(IntDir)%s.obj</ObjectFileName></ClCompile>\n", rel(C[o]), objrel; next }
        if (o in A) { d = A[o]; sub(/\/[^\/]*$/, "", d); printf "    <Nasm Include=\"%s\"><ObjectFileName>$(IntDir)%s.obj</ObjectFileName><ExtraInclude>%s</ExtraInclude></Nasm>\n", rel(A[o]), objrel, rel(d); next }
        if (o in R) { printf "    <ResourceCompile Include=\"%s\"><ResourceOutputFileName>$(IntDir)%s.res</ResourceOutputFileName></ResourceCompile>\n", rel(R[o]), objrel; next }
        print "ERROR: no source for object " o > "/dev/stderr"; exit 1 }'
    echo "  </ItemGroup>"
    echo "</Project>"
  } > "$IT"
  echo "   $lib: $(grep -c '<ClCompile' "$IT") C, $(grep -c '<Nasm' "$IT") asm -> $dll [$deps]"
done

cat > "$O/nasm-$PLAT.props" <<XML
<?xml version="1.0" encoding="utf-8"?>
<!-- generated by msvc/regen/gen-ffmpeg.sh - do not edit -->
<Project xmlns="http://schemas.microsoft.com/developer/msbuild/2003">
  <PropertyGroup>
    <NasmFlags>$X86ASMFLAGS</NasmFlags>
  </PropertyGroup>
</Project>
XML

# project shells: written once, then hand-maintained (project references below)
for lib in $LIBS; do
  [ -f "$P/$lib.vcxproj" ] && continue
  refs=""
  case $lib in
    swresample|swscale) refs="avutil";;
    avcodec)  refs="avutil swresample ../libs/dav1d/dav1d ../libs/speex/speex ../libs/opencore-amr/opencore-amrnb ../libs/opencore-amr/opencore-amrwb";;
    avformat) refs="avutil avcodec swresample ../libs/libxml2/libxml2 ../libs/bzip2/bzip2";;
    avfilter) refs="avutil avcodec avformat swscale swresample";;
  esac
  {
    cat <<XML
<?xml version="1.0" encoding="utf-8"?>
<Project DefaultTargets="Build" ToolsVersion="17.0" xmlns="http://schemas.microsoft.com/developer/msbuild/2003">
  <ItemGroup Label="ProjectConfigurations">
    <ProjectConfiguration Include="Debug|Win32"><Configuration>Debug</Configuration><Platform>Win32</Platform></ProjectConfiguration>
    <ProjectConfiguration Include="Debug|x64"><Configuration>Debug</Configuration><Platform>x64</Platform></ProjectConfiguration>
    <ProjectConfiguration Include="Release|Win32"><Configuration>Release</Configuration><Platform>Win32</Platform></ProjectConfiguration>
    <ProjectConfiguration Include="Release|x64"><Configuration>Release</Configuration><Platform>x64</Platform></ProjectConfiguration>
  </ItemGroup>
  <PropertyGroup Label="Globals">
    <ProjectName>$lib</ProjectName>
    <RootNamespace>$lib</RootNamespace>
  </PropertyGroup>
  <Import Project="\$(VCTargetsPath)\Microsoft.Cpp.Default.props" />
  <PropertyGroup Label="Configuration">
    <ConfigurationType>DynamicLibrary</ConfigurationType>
  </PropertyGroup>
  <Import Project="\$(MSBuildThisFileDirectory)ffmpeg-compiler.props" />
  <Import Project="\$(MSBuildThisFileDirectory)\$(FFmpegCompiler)\items-$lib-\$(Platform).props" />
  <Import Project="\$(MSBuildThisFileDirectory)ffmpeg.props" />
  <Import Project="\$(VCTargetsPath)\Microsoft.Cpp.props" />
  <ItemGroup>
XML
    for r in $refs; do echo "    <ProjectReference Include=\"\$(MSBuildThisFileDirectory)$(echo "$r" | tr '/' '\\').vcxproj\"><LinkLibraryDependencies>false</LinkLibraryDependencies></ProjectReference>"; done
    cat <<XML
  </ItemGroup>
  <Import Project="\$(VCTargetsPath)\Microsoft.Cpp.targets" />
</Project>
XML
  } > "$P/$lib.vcxproj"
  echo "   wrote $lib.vcxproj"
done
echo "== done ($CC, $PLAT)"
